<?php
namespace App\Services;use App\Models\TransportService;use Carbon\Carbon;use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
class TransportProgrammingCopyService{public function __construct(private TransportSchedulingService$scheduling,private TransportAuditService$audit){}public function copy(int$company,array$data,int$user):int{$from=Carbon::parse($data['source_from']);$to=Carbon::parse($data['source_to']);$target=Carbon::parse($data['target_from']);$offset=$from->diffInDays($target,false);$sources=TransportService::forCompany($company)->whereBetween('service_date',[$from,$to])->whereNot('status','cancelled')->orderBy('scheduled_start_at')->get();if($sources->isEmpty())throw ValidationException::withMessages(['copy'=>'No existen servicios en el período de origen.']);return DB::transaction(function()use($sources,$offset,$company,$user,$data){$count=0;foreach($sources as$s){$payload=['transport_route_id'=>$s->transport_route_id,'service_type'=>$s->service_type,'shift'=>$s->shift,'scheduled_start_at'=>$s->scheduled_start_at->copy()->addDays($offset),'scheduled_arrival_at'=>$s->scheduled_arrival_at->copy()->addDays($offset),'planned_vehicle_id'=>$s->planned_vehicle_id,'planned_driver_id'=>$s->planned_driver_id,'planned_monitor_id'=>$s->planned_monitor_id,'notes'=>'Copiado: '.$data['reason'],'generation_source'=>'copied'];$this->scheduling->create($payload,$company,$user);$count++;}$this->audit->record($company,'transport_programming_copied','programming',0,$user,['count'=>$count,'source_from'=>$data['source_from'],'target_from'=>$data['target_from']]);return$count;});}}
